  draw.text('(a)').font({size:18,style:'italic',family:'serif'}).center(300,612);
  draw.text('(b)').font({size:18,style:'italic',family:'serif'}).center(880,612);

  // ---- dynamic groups ----
  var gA = draw.group().attr('clip-path','url(#clipA)');
  var gB = draw.group().attr('clip-path','url(#clipB)');
  var lblA = draw.group();
  var lblB = draw.group();

  var state = { qPos:0.7, focus:'a', sP:0.18, aP:150 };

  function norm(v){ var L=Math.hypot(v[0],v[1])||1; return [v[0]/L,v[1]/L]; }
  function lineEnds(P,m,len){ return [[P[0]-len,P[1]-len*m],[P[0]+len,P[1]+len*m]]; }
  function drawLine(g,P,m,color,w,dash){ var e=lineEnds(P,m,460); var l=g.line(e[0][0],e[0][1],e[1][0],e[1][1]).stroke({color:color,width:w,linecap:'round'}); if(dash)l.attr('stroke-dasharray','6,5'); return l; }
  function drawSeg(g,P,d,len,color,w){ var e=[P[0]+d[0]*len,P[1]+d[1]*len]; return g.line(P[0],P[1],e[0],e[1]).stroke({color:color,width:w,linecap:'round'}); }

  function tangentA(){ var s=state.sP, e=0.001; var p1=curveA(s-e),p2=curveA(s+e); return (p2[1]-p1[1])/(p2[0]-p1[0]); }
  function tangentBdir(){ var a=state.aP*Math.PI/180; var d=[Math.sin(a),Math.cos(a)]; if(d[0]<0){d[0]=-d[0];d[1]=-d[1];} return d; }

  function arcArrow(g,P,a0,a1,r){
    var dstr='', n=24, px,py;
    for(var i=0;i<=n;i++){ var t=a0+(a1-a0)*i/n; var x=P[0]+r*Math.cos(t), y=P[1]+r*Math.sin(t); dstr+=(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)+' '; px=x;py=y; }
    g.path(dstr).fill('none').stroke({color:GREY,width:2.4});
    // arrowhead along tangent direction at end
    var dir=[Math.cos(a1),Math.sin(a1)]; var perp=[-dir[1],dir[0]];
    var b1=[px+dir[0]*12+perp[0]*6, py+dir[1]*12+perp[1]*6];
    var b2=[px+dir[0]*12-perp[0]*6, py+dir[1]*12-perp[1]*6];
    var tip=[px+dir[0]*2, py+dir[1]*2];
    g.polygon([tip,b1,b2].map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' ')).fill(GREY);
  }

  function renderPanel(g,lbl,kind,focus){
    g.clear(); lbl.clear();
    var P, Q, mSec, tanSlope, tanDir;
    if(kind==='a'){
      P=curveA(state.sP);
      var sQ=state.sP+state.qPos*(0.78-state.sP);
      Q=curveA(sQ);
      mSec=(Q[1]-P[1])/(Q[0]-P[0]);
      tanSlope=tangentA(); tanDir=norm([1,tanSlope]); if(tanDir[0]<0){tanDir[0]=-tanDir[0];tanDir[1]=-tanDir[1];}
    } else {
      P=circleB(state.aP);
      var aQ=state.aP - state.qPos*(state.aP-20);
      Q=circleB(aQ);
      mSec=(Q[1]-P[1])/(Q[0]-P[0]);
      tanDir=tangentBdir(); tanSlope=tanDir[1]/tanDir[0];
    }
    var secDir=norm([Q[0]-P[0],Q[1]-P[1]]); if(secDir[0]<0){secDir[0]=-secDir[0];secDir[1]=-secDir[1];}

