    var R=175;
    var tEnd=[P[0]+tanDir[0]*R,P[1]+tanDir[1]*R];
    var sEnd=[P[0]+secDir[0]*R,P[1]+secDir[1]*R];
    g.polygon([P,tEnd,sEnd].map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' '))
      .fill({color:MAGL,opacity:0.42}).stroke('none');
