    lbl.text('P').font({size:16,style:'italic',family:'serif'}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(P[0]-22,P[1]-22);
    lbl.text('Q').font({size:16,style:'italic',family:'serif'}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(Q[0]+6,Q[1]+8);
    lbl.text('Tangent').font({size:15,family:'sans-serif'}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(tEnd[0]-30,tEnd[1]-30);
    lbl.text('line').font({size:15,family:'sans-serif'}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(tEnd[0]-12,tEnd[1]-12);
    lbl.text('Secant').font({size:15,family:'sans-serif'}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(sEnd[0]-2,sEnd[1]-16);
    lbl.text('line').font({size:15,family:'sans-serif'}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(sEnd[0]+8,sEnd[1]+2);

    // slope readout for focus panel
    if(focus){
      var rx = kind==='a'?95:650, ry=kind==='a'?70:60;
      var t1=lbl.text('secant slope = '+mSec.toFixed(3)).font({size:13,family:'sans-serif',fill:MAG}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(rx,ry);
      lbl.text('tangent slope = '+tanSlope.toFixed(3)).font({size:13,family:'sans-serif',fill:MAG}).attr({'paint-order':'stroke',stroke:'#fff','stroke-width':3}).move(rx,ry+18);
    }

    // draggable P handle
    var h=g.circle(22).center(P[0],P[1]).fill('transparent').css('cursor','grab');
    h.on('pointerdown',function(ev){ startDrag(ev,kind); });
  }

  function renderAll(){
    renderPanel(gA,lblA,'a',state.focus==='a');
    renderPanel(gB,lblB,'b',state.focus==='b');
  }

  // ---- drag P ----
  function svgPoint(ev){
    var r=draw.node.getBoundingClientRect();
    var sc=Math.min(r.width/1200,r.height/640);
    var ox=(r.width-1200*sc)/2, oy=(r.height-640*sc)/2;
    return [ (ev.clientX-r.left-ox)/sc, (ev.clientY-r.top-oy)/sc ];
  }
  function startDrag(ev,kind){
    ev.preventDefault();
    function mv(e){
      var p=svgPoint(e);
      if(kind==='a'){ var s=(p[0]-90)/380; state.sP=Math.max(0.05,Math.min(0.55,s)); }
      else { var ang=Math.atan2(CY-p[1],p[0]-CX)*180/Math.PI; state.aP=Math.max(95,Math.min(210,ang)); }
      renderAll();
    }
    function up(){ window.removeEventListener('pointermove',mv); window.removeEventListener('pointerup',up); }
    window.addEventListener('pointermove',mv); window.addEventListener('pointerup',up);
  }

  // ---- controls ----
  window.update_qPosition=function(v){ state.qPos=v; renderAll(); };
  window.toggle_panel=function(on){ state.focus=on?'b':'a'; renderAll(); };

  // ---- demo steps ----
  var steps=[
    {t:'A secant through two points',n:'With Q far from P, the line through P and Q is an ordinary secant that cuts across the curve; its slope is the average rate of change between the two points.',q:0.85,c:false},
    {t:'Q slides toward P',n:'Drag the slider so Q moves along the curve toward P: the secant line rotates and the slope readout changes continuously, tracing the fan of intermediate secants.',q:0.4,c:false},
    {t:'The limit is the tangent',n:'As Q reaches P the secant line coincides with the tangent line and the slope readout stops changing — that limiting slope is the tangent’s slope, the core of the derivative.',q:0.02,c:false},
    {t:'Same limit on a circle',n:'Switch to the circle and repeat: the secant lines again rotate into a single limiting line at P, which is exactly the classical tangent to the circle — the definition generalizes.',q:0.4,c:true},
    {t:'Move the base point P',n:'Drag P to a new location on the curve or circle and watch the entire fan and the tangent line re-aim, showing the tangent direction is a property of the chosen point on the curve.',q:0.4,c:true}
  ];
  var cur=0;
  function applyStep(i){
    cur=Math.max(0,Math.min(steps.length-1,i));
    var s=steps[cur];
    document.getElementById('qPositionInput').value=s.q;
    document.getElementById('qPositionVal').value=s.q.toFixed(2);
    document.getElementById('panelInput').checked=s.c;
    document.getElementById('demoNarration').textContent=s.n;
    document.getElementById('stepLabel').textContent=(cur+1)+' / '+steps.length;
    state.qPos=s.q; state.focus=s.c?'b':'a'; renderAll();
  }
  window.nextStep=function(){ applyStep(cur+1); };
  window.prevStep=function(){ applyStep(cur-1); };

  renderAll();
  window.__markRendered();
})();
// @FIGURE_CODE_END

