(function(){
  var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
  draw.viewbox(0,0,1200,640);
  var CYAN='#29abe2', MAG='#a64d9e', MAGL='#c98fc0', GREY='#b3b3b3';

  // clip paths - tightly bound to each panel
  var defs = draw.defs();
  defs.clip().rect(30,20,560,580).id('clipA');
  defs.clip().rect(600,20,580,580).id('clipB');

  // ---- static geometry ----
  // panel (a) axes
  var axG = draw.group();
  axG.line(70,520,540,520).stroke({color:'#000',width:1.6});
  axG.polygon('540,520 528,515 528,525').fill('#000');
  axG.line(70,540,70,40).stroke({color:'#000',width:1.6});
  axG.polygon('70,40 65,52 75,52').fill('#000');
  axG.text('x').font({size:16,style:'italic',family:'serif'}).move(524,500);
  axG.text('y').font({size:16,style:'italic',family:'serif'}).move(80,38);

  // curve A: gentle hump rising then falling
  function curveA(s){ var x=90+s*380; var y=520-(60+150*Math.sin(Math.PI*s*0.85)); return [x,y]; }
  var ptsA=[]; for(var i=0;i<=120;i++){ptsA.push(curveA(i/120));}
  draw.polyline(ptsA.map(function(p){return p[0]+','+p[1];}).join(' '))
      .fill('none').stroke({color:CYAN,width:3,linecap:'round'});

  // circle B
  var CX=880, CY=360, R=150;
  draw.circle(2*R).center(CX,CY).fill('none').stroke({color:CYAN,width:3});
  function circleB(aDeg){ var a=aDeg*Math.PI/180; return [CX+R*Math.cos(a), CY-R*Math.sin(a)]; }

