  draw.text('(a)').font({size:18,style:'italic',family:'serif'}).center(300,612);
  draw.text('(b)').font({size:18,style:'italic',family:'serif'}).center(880,612);

  // ---- dynamic groups ----
  var gA = draw.group().attr('clip-path','url(#clipA)');
  var gB = draw.group().attr('clip-path','url(#clipB)');
  var lblA = draw.group();
  var lblB = draw.group();

  var state = { qPos:0.7, focus:'a', sP:0.18, aP:150 };

  function norm(v){ var L=Math.hypot(v[0],v[1])||1; return [v[0]/L,v[1]/L]; }

  function drawLine(g,P,mSvg,color,w,dash){
    var len=160;
    var dx=1, dy=mSvg;
    var L=Math.hypot(dx,dy)||1;
    dx/=L; dy/=L;
    var l=g.line(P[0]-dx*len,P[1]-dy*len,P[0]+dx*len,P[1]+dy*len)
      .stroke({color:color,width:w,linecap:'round'});
    if(dash)l.attr('stroke-dasharray','6,5');
    return l;
  }

  function mathSlope(svgSlope){ return -svgSlope; }

  function tangentASvg(){ var s=state.sP, e=0.001; var p1=curveA(s-e),p2=curveA(s+e); return (p2[1]-p1[1])/(p2[0]-p1[0]); }
  function tangentBdir(){ var a=state.aP*Math.PI/180; var d=[Math.sin(a),Math.cos(a)]; if(d[0]<0){d[0]=-d[0];d[1]=-d[1];} return d; }

  // Double concentric arc arrow
  function doubleArcArrow(g,P,a0,a1,r1,r2){
    var n=28;
    // Outer arc
    var d1='',px1,py1;
    for(var i=0;i<=n;i++){ var t=a0+(a1-a0)*i/n; var x=P[0]+r1*Math.cos(t), y=P[1]+r1*Math.sin(t); d1+=(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)+' '; px1=x;py1=y; }
    g.path(d1).fill('none').stroke({color:GREY,width:2.2});
    // Inner arc
    var d2='',px2,py2;
    for(var i=0;i<=n;i++){ var t=a0+(a1-a0)*i/n; var x=P[0]+r2*Math.cos(t), y=P[1]+r2*Math.sin(t); d2+=(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)+' '; px2=x;py2=y; }
    g.path(d2).fill('none').stroke({color:GREY,width:2.2});
    // Arrowhead on outer arc
    var dir=[Math.cos(a1),Math.sin(a1)]; var perp=[-dir[1],dir[0]];
    var tip=[px1+dir[0]*3, py1+dir[1]*3];
    var b1=[px1-dir[0]*14+perp[0]*7, py1-dir[1]*14+perp[1]*7];
    var b2=[px1-dir[0]*14-perp[0]*7, py1-dir[1]*14-perp[1]*7];
    g.polygon([tip,b1,b2].map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' ')).fill(GREY);
    // Small arrowhead on inner arc
    var tip2=[px2+dir[0]*3, py2+dir[1]*3];
    var b3=[px2-dir[0]*10+perp[0]*5, py2-dir[1]*10+perp[1]*5];
    var b4=[px2-dir[0]*10-perp[0]*5, py2-dir[1]*10-perp[1]*5];
    g.polygon([tip2,b3,b4].map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' ')).fill(GREY);
  }

  function renderPanel(g,lbl,kind){
    g.clear(); lbl.clear();
    var P, Q, mSecSvg, tanSvgSlope, tanDir;
    if(kind==='a'){
      P=curveA(state.sP);
      var sQ=state.sP+state.qPos*(0.78-state.sP);
      Q=curveA(sQ);
      mSecSvg=(Q[1]-P[1])/(Q[0]-P[0]);
      tanSvgSlope=tangentASvg();
      tanDir=norm([1,tanSvgSlope]); if(tanDir[0]<0){tanDir[0]=-tanDir[0];tanDir[1]=-tanDir[1];}
    } else {
      P=circleB(state.aP);
      var aQ=state.aP - state.qPos*(state.aP-20);
      Q=circleB(aQ);
      mSecSvg=(Q[1]-P[1])/(Q[0]-P[0]);
      tanDir=tangentBdir();
      tanSvgSlope=tanDir[1]/tanDir[0];
    }
    var secDir=norm([Q[0]-P[0],Q[1]-P[1]]); if(secDir[0]<0){secDir[0]=-secDir[0];secDir[1]=-secDir[1];}

    // ghost fan
    for(var k=1;k<=4;k++){
      var f=state.qPos*(k/5);
      var Qg = kind==='a'? curveA(state.sP+f*(0.78-state.sP)) : circleB(state.aP - f*(state.aP-20));
      var mg=(Qg[1]-P[1])/(Qg[0]-P[0]);
      drawLine(g,P,mg,MAGL,1.4);
    }

    // wedge between tangent and current secant
    var Rw=130;
    var tEnd=[P[0]+tanDir[0]*Rw,P[1]+tanDir[1]*Rw];
    var sEnd=[P[0]+secDir[0]*Rw,P[1]+secDir[1]*Rw];
    g.polygon([P,tEnd,sEnd].map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' '))
      .fill({color:MAGL,opacity:0.55}).stroke('none');

    // double arc arrow secant->tangent
    var a0=Math.atan2(secDir[1],secDir[0]), a1=Math.atan2(tanDir[1],tanDir[0]);
    doubleArcArrow(g,P,a0,a1,115,95);

    // current secant + tangent
    drawLine(g,P,mSecSvg,MAG,2.2);
    drawLine(g,P,tanSvgSlope,MAG,2.6);

    // dots
    g.circle(10).center(P[0],P[1]).fill(CYAN).stroke({color:'#fff',width:1.5});
    g.circle(10).center(Q[0],Q[1]).fill(CYAN).stroke({color:'#fff',width:1.5});

    // Panel opacity based on focus
    var isFocused = (state.focus==='a' && kind==='a') || (state.focus==='b' && kind==='b');
    g.opacity(isFocused?1:0.35);
    lbl.opacity(isFocused?1:0.35);

    // Labels with careful positioning
    var halo={'paint-order':'stroke',stroke:'#fff','stroke-width':4,'stroke-linejoin':'round'};

    // P label - to the left and slightly below
    lbl.text('P').font({size:18,style:'italic',family:'serif'}).attr(halo).move(P[0]-28,P[1]+4);

    // Q label - below and slightly right of Q dot
    lbl.text('Q').font({size:18,style:'italic',family:'serif'}).attr(halo).move(Q[0]+4,Q[1]+14);

    // Tangent line label - far along tangent direction, upper area
    var tLblDist=175;
    var tLblPos=[P[0]+tanDir[0]*tLblDist, P[1]+tanDir[1]*tLblDist];
    lbl.text('Tangent').font({size:15,family:'sans-serif'}).attr(halo).move(tLblPos[0]-40,tLblPos[1]-22);
    lbl.text('line').font({size:15,family:'sans-serif'}).attr(halo).move(tLblPos[0]-22,tLblPos[1]-4);

    // Secant line label - far along secant direction, to the right
    var sLblDist=175;
    var sLblPos=[P[0]+secDir[0]*sLblDist, P[1]+secDir[1]*sLblDist];
    lbl.text('Secant').font({size:15,family:'sans-serif'}).attr(halo).move(sLblPos[0]+2,sLblPos[1]-20);
    lbl.text('line').font({size:15,family:'sans-serif'}).attr(halo).move(sLblPos[0]+12,sLblPos[1]-2);

    // Slope readouts - larger, in clear corner
    var mSecMath = mathSlope(mSecSvg);
    var mTanMath = mathSlope(tanSvgSlope);
    var rx = kind==='a'?90:640, ry=kind==='a'?60:50;
    lbl.text('secant slope = '+mSecMath.toFixed(3)).font({size:15,family:'sans-serif',fill:MAG}).attr(halo).move(rx,ry);
    lbl.text('tangent slope = '+mTanMath.toFixed(3)).font({size:15,family:'sans-serif',fill:MAG}).attr(halo).move(rx,ry+20);

    // draggable P handle
    var h=g.circle(26).center(P[0],P[1]).fill('transparent').css('cursor','grab');
    h.on('pointerdown',function(ev){ startDrag(ev,kind); });
    h.on('mousemove',function(ev){ showTooltip('Drag to move P',ev); });
    h.on('mouseleave',function(){ hideTooltip(); });
  }

  function renderAll(){
    renderPanel(gA,lblA,'a');
    renderPanel(gB,lblB,'b');
  }

  // ---- drag P ----
  function svgPoint(ev){
    var r=draw.node.getBoundingClientRect();
    var sc=Math.min(r.width/1200,r.height/640);
    var ox=(r.width-1200*sc)/2, oy=(r.height-640*sc)/2;
    return [ (ev.clientX-r.left-ox)/sc, (ev.clientY-r.top-oy)/sc ];
  }
  function startDrag(ev,kind){
    ev.preventDefault();
    function mv(e){
      var p=svgPoint(e);
      if(kind==='a'){ var s=(p[0]-90)/380; state.sP=Math.max(0.05,Math.min(0.55,s)); }
      else { var ang=Math.atan2(CY-p[1],p[0]-CX)*180/Math.PI; state.aP=Math.max(95,Math.min(210,ang)); }
      renderAll();
    }
    function up(){ window.removeEventListener('pointermove',mv); window.removeEventListener('pointerup',up); }
    window.addEventListener('pointermove',mv);
    window.addEventListener('pointerup',up);
  }

  // ---- controls ----
  window.update_qPosition=function(v){ state.qPos=v; renderAll(); };
  window.toggle_panel=function(on){ state.focus=on?'b':'a'; renderAll(); };

  // ---- demo steps ----
  var steps=[
    {t:'A secant through two points',n:'With Q far from P, the line through P and Q is an ordinary secant that cuts across the curve; its slope is the average rate of change between the two points.',q:0.85,c:false},
    {t:'Q slides toward P',n:'Drag the slider so Q moves along the curve toward P: the secant line rotates and the slope readout changes continuously, tracing the fan of intermediate secants.',q:0.4,c:false},
    {t:'The limit is the tangent',n:'As Q reaches P the secant line coincides with the tangent line and the slope readout stops changing \u2014 that limiting slope is the tangent\u2019s slope, the core of the derivative.',q:0.02,c:false},
    {t:'Same limit on a circle',n:'Switch to the circle and repeat: the secant lines again rotate into a single limiting line at P, which is exactly the classical tangent to the circle \u2014 the definition generalizes.',q:0.4,c:true},
    {t:'Move the base point P',n:'Drag P to a new location on the curve or circle and watch the entire fan and the tangent line re-aim, showing the tangent direction is a property of the chosen point on the curve.',q:0.4,c:true}
  ];
  var cur=0;
  function applyStep(i){
    cur=Math.max(0,Math.min(steps.length-1,i));
    var s=steps[cur];
    document.getElementById('qPositionInput').value=s.q;
    document.getElementById('qPositionVal').value=s.q.toFixed(2);
    document.getElementById('panelInput').checked=s.c;
    document.getElementById('demoNarration').textContent=s.n;
    document.getElementById('stepLabel').textContent=(cur+1)+' / '+steps.length;
    state.qPos=s.q; state.focus=s.c?'b':'a'; renderAll();
  }
  window.nextStep=function(){ applyStep(cur+1); };
  window.prevStep=function(){ applyStep(cur-1); };

  renderAll();
  window.__markRendered();
})();
